import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百二十四章 水界是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/124第一百二十四章 水界是什么.md","filePath":"meditation/巴利文大藏经/124第一百二十四章 水界是什么.md"}'),r={name:"meditation/巴利文大藏经/124第一百二十四章 水界是什么.md"};function _(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百二十四章-水界是什么" tabindex="-1">第一百二十四章 水界是什么？ <a class="header-anchor" href="#第一百二十四章-水界是什么" aria-label="Permalink to &quot;第一百二十四章 水界是什么？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>4.第四品</p><p>相应部14相应30经/四界经(界相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，世间有四界，是哪四界呢？就是地界、水界、火界、风界。什么是地界呢？就是世间具有坚固性质的领域、范围，地界也被称为地大，什么是地大呢？就是具有坚固的性质，有承载保持的作用，比如大地坚固，承载万物，有保持不动的作用，又比如世间人的毛发、指甲、牙齿、皮肉、骨头等等也具有坚固、承载、保持的作用，也被称为人身体上的地大。</p><p>什么是水界呢？就是世间具有湿润性质的领域、范围，水界也被称为水大，什么是水大呢？就是具有潮湿的性质，有聚集、凝结的作用，比如世间的雨水滋润世间万物，让万物湿润，这些水还能聚集成江河、湖泊、海洋。又比如世间人的血液、泪水、口水、鼻涕、尿液等等也具有潮湿、聚集、滋润的作用，也被称为人身体上的水大。</p><p>什么是火界呢？就是世间具有温热性质的领域、范围，火界也被称为火大，什么是火大呢？就是具有温暖的性质，有催生、成熟的作用，比如世间春夏的气候，温暖让万物开始复苏、生长、成熟。又比如世间人的身体温度，以及身体中的各种暖气等等也具有温暖、催生、成熟的作用，也被称为人身体上的火大。</p><p>什么是风界呢？就是世间具有移动、流通性质的领域、范围，风界也被称为风大，什么是风大呢？就是具有流动的性质，有传递、传播的作用，比如世间的各种风，让各种气互相流通，世间万物因为气的流通而得以生长、生存。又比如世间人呼吸空气，获取能够让自己持续生存下去的气，由于呼吸而让身体内的气与外界的气流通，也具有流动、传递、传播的作用，也被称为人身体上的风大。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',9)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
